"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def updateInventory(inventory, transactions):
    for transaction in transactions:
        item = transaction.item
        type = transaction.type
        quantity = transaction.quantity
        if (item not in inventory):
            inventory[item] = 0
        if (type == 'purchase'):
            inventory[item] = (inventory[item] - quantity)
        elif (type == 'delivery'):
            inventory[item] = (inventory[item] + quantity)
        if (inventory[item] < 0):
            print(f"Insufficient stock for {item}")
    return inventory


class Transaction:
    def __init__(self, item, type, quantity):
        self.item = item
        self.type = type
        self.quantity = quantity
inventory = {
    'Apples': 50,
    'Bananas': 20
}
transactions = [
    Transaction('Apples', 'purchase', 10),
    Transaction('Bananas', 'delivery', 15),
    Transaction('Oranges', 'purchase', 5),   # Oranges auto‑added with stock 0
    Transaction('Apples', 'purchase', 45),   # Will trigger insufficient stock
]
updated = updateInventory(inventory, transactions)
print(updated)
